--
-- Table structure for table `materials`
--

DROP TABLE IF EXISTS `materials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `materials` (
  `id_Materials` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nombre del material',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Descripción detallada',
  `unit_of_measure` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unidad de medida (Bulto, Metro³, Unidad, Kilo, etc.)',
  `unit_cost` decimal(15,2) DEFAULT NULL COMMENT 'Costo unitario del material',
  `current_stock` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Stock actual',
  `minimum_stock` decimal(15,2) DEFAULT NULL COMMENT 'Stock mínimo para alertas de reposición',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Categoría (Cemento, Arena, Hierro, etc.)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo' COMMENT 'Estado: Activo, Inactivo',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de creación',
  `updated_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'Fecha de última actualización',
  PRIMARY KEY (`id_Materials`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_materials_name` (`name`),
  KEY `idx_materials_status` (`status`),
  KEY `idx_materials_category` (`category`),
  KEY `idx_materials_stock_low` (`current_stock`,`minimum_stock`)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla de materiales de construcción con stock';
/*!40101 SET character_set_client = @saved_cs_client */;

